"""State merging for offline coordination.

A state is a dict of the form::

    {"clock": {node: count}, "records": {key: [value, deleted, clock, writer]}}

``clock`` maps non-empty node names to non-negative integer counters.
Each record is a four-item list ``[value, deleted, clock, writer]`` where
``value`` is a str (always ``""`` for a deleted record), ``deleted`` is a
bool, ``clock`` is the record's vector clock (it must contain ``writer`` and
no component may exceed the outer state clock; missing nodes count as 0),
and ``writer`` is a non-empty str.

See :func:`merge_states` for the reconciliation rules.
"""

from __future__ import annotations

from typing import Any

CLOCK = "clock"
RECORDS = "records"


def _is_int(value: Any) -> bool:
    # bool is a subclass of int, but a counter must never be a bool.
    return isinstance(value, int) and not isinstance(value, bool)


def _is_nonempty_str(value: Any) -> bool:
    return isinstance(value, str) and value != ""


def _validated_clock(
    clock: Any, *, where: str, bound: dict[str, int] | None = None
) -> dict[str, int]:
    """Validate a clock mapping and return a fresh dict copy.

    When ``bound`` is given, every component must be <= the corresponding
    bound value; nodes absent from the bound are treated as 0.
    """
    if not isinstance(clock, dict):
        raise TypeError(f"{where} clock must be a dict")
    result: dict[str, int] = {}
    for node, count in clock.items():
        if not isinstance(node, str):
            raise TypeError(f"{where} clock node must be a str")
        if node == "":
            raise ValueError(f"{where} clock node must be non-empty")
        if not _is_int(count):
            raise TypeError(f"{where} clock count for {node!r} must be an int")
        if count < 0:
            raise ValueError(f"{where} clock count for {node!r} must be non-negative")
        result[node] = count
    if bound is not None:
        for node, count in result.items():
            limit = bound.get(node, 0)
            if count > limit:
                raise ValueError(
                    f"{where} clock count for {node!r} ({count}) exceeds the "
                    f"state clock ({limit})"
                )
    return result


def _validated_record(
    entry: Any, *, key: str, state_clock: dict[str, int]
) -> list[Any]:
    """Validate one record and return a fresh list with a copied clock."""
    where = f"record for key {key!r}"
    if not isinstance(entry, list):
        raise TypeError(f"{where} must be a list")
    if len(entry) != 4:
        raise ValueError(f"{where} must have exactly four items")
    value, deleted, clock, writer = entry
    if not isinstance(value, str):
        raise TypeError(f"{where} value must be a str")
    if not isinstance(deleted, bool):
        raise TypeError(f"{where} deleted flag must be a bool")
    if deleted and value != "":
        raise ValueError(f"{where} is deleted but its value is not empty")
    clock_copy = _validated_clock(clock, where=where, bound=state_clock)
    if not isinstance(writer, str):
        raise TypeError(f"{where} writer must be a str")
    if writer == "":
        raise ValueError(f"{where} writer must be non-empty")
    if writer not in clock_copy:
        raise ValueError(f"{where} writer {writer!r} is missing from its clock")
    return [value, deleted, clock_copy, writer]


def _validated_state(state: Any) -> tuple[dict[str, int], dict[str, list[Any]]]:
    """Validate a whole state and return fresh copies of its contents."""
    if not isinstance(state, dict):
        raise TypeError("state must be a dict")
    if set(state.keys()) != {CLOCK, RECORDS}:
        raise ValueError("state must contain exactly the keys 'clock' and 'records'")
    clock = _validated_clock(state[CLOCK], where="state")
    raw_records = state[RECORDS]
    if not isinstance(raw_records, dict):
        raise TypeError("state records must be a dict")
    records: dict[str, list[Any]] = {}
    for key, entry in raw_records.items():
        if not isinstance(key, str):
            raise TypeError("record key must be a str")
        if key == "":
            raise ValueError("record key must be non-empty")
        records[key] = _validated_record(entry, key=key, state_clock=clock)
    return clock, records


def _dominates(winner: dict[str, int], loser: dict[str, int]) -> bool:
    """True iff every component of winner is >= and at least one is >.

    Nodes missing from either clock are treated as 0.
    """
    nodes = set(winner) | set(loser)
    return all(winner.get(node, 0) >= loser.get(node, 0) for node in nodes) and any(
        winner.get(node, 0) > loser.get(node, 0) for node in nodes
    )


def _record_sort_key(record: list[Any]) -> tuple[Any, ...]:
    value, deleted, clock, writer = record
    return (
        clock[writer],
        writer,
        deleted,
        value,
        tuple(sorted(clock.items())),
    )


def _resolve_record(left: list[Any], right: list[Any]) -> list[Any]:
    # Identical records simply survive.
    if left == right:
        return left
    left_clock = left[2]
    right_clock = right[2]
    if _dominates(left_clock, right_clock):
        return left
    if _dominates(right_clock, left_clock):
        return right
    # Concurrent updates: compare by the prescribed Python tuple order.
    return left if _record_sort_key(left) >= _record_sort_key(right) else right


def _remote_need(
    remote_record: list[Any], local_clock: dict[str, int]
) -> dict[str, list[int]]:
    """Clock components the local state is missing before this record applies.

    The prerequisite vector is the remote record clock with its own writer
    component decremented by one.  Each component where the local outer clock
    is behind contributes the closed interval ``[local + 1, prerequisite]``.
    """
    _, _, remote_clock, writer = remote_record
    need: dict[str, list[int]] = {}
    for node in sorted(set(local_clock) | set(remote_clock)):
        prerequisite = remote_clock.get(node, 0) - (1 if node == writer else 0)
        local_count = local_clock.get(node, 0)
        if local_count < prerequisite:
            need[node] = [local_count + 1, prerequisite]
    return need


def preview_changes(local: dict[str, Any], remote: dict[str, Any]) -> dict[str, Any]:
    """Preview per-key decisions implied by merging ``remote`` into ``local``.

    The state contract is the same as for :func:`merge_states`.  Inputs are
    never modified and every call returns brand-new, deeply independent
    objects.

    The result is ``{"items": items, "version": 1}`` with one item per key of
    ``remote["records"]`` in ascending key order.  Each item has the key order
    ``decision, key, need, winner``:

    * ``need`` lists the outer-clock components missing locally for the
      remote record to be causally ready (its clock with the writer component
      decremented by one), nodes ascending, values as closed
      ``[start, end]`` intervals (missing components count as 0).
    * When ``need`` is non-empty, ``decision`` is ``"missing"`` and
      ``winner`` is ``None``.
    * Otherwise the decision is, in order: ``"apply"``/``"remote"`` when the
      local record is absent or the remote record dominates it,
      ``"duplicate"``/``"equal"`` for equal records, ``"stale"``/``"local"``
      when the local record dominates, and ``"conflict"`` with the
      :func:`merge_states` tie-break winner (``"remote"`` or ``"local"``) for
      concurrent records.

    Type violations raise :class:`TypeError`; all other constraint violations
    raise :class:`ValueError`.
    """
    local_clock, local_records = _validated_state(local)
    _, remote_records = _validated_state(remote)

    items: list[dict[str, Any]] = []
    for key in sorted(remote_records):
        remote_record = remote_records[key]
        local_record = local_records.get(key)
        need = _remote_need(remote_record, local_clock)

        if need:
            decision, winner = "missing", None
        elif local_record is None:
            decision, winner = "apply", "remote"
        elif local_record == remote_record:
            decision, winner = "duplicate", "equal"
        elif _dominates(remote_record[2], local_record[2]):
            decision, winner = "apply", "remote"
        elif _dominates(local_record[2], remote_record[2]):
            decision, winner = "stale", "local"
        else:
            # Concurrent updates: the same tuple arbitration as merge_states.
            if _record_sort_key(remote_record) >= _record_sort_key(local_record):
                winner = "remote"
            else:
                winner = "local"
            decision = "conflict"

        items.append(
            {"decision": decision, "key": key, "need": need, "winner": winner}
        )

    return {"items": items, "version": 1}


def merge_states(left: dict[str, Any], right: dict[str, Any]) -> dict[str, Any]:
    """Merge two states and return a brand-new state without mutating inputs.

    Rules:

    * The output clock takes the per-node maximum (missing nodes count as 0).
    * A record present on only one side is kept as-is.
    * Identical records are kept.
    * If one record's clock has every component >= the other's with at least
      one strictly greater, that record wins.
    * Otherwise the record with the larger
      ``(clock[writer], writer, deleted, value, tuple(sorted(clock.items())))``
      Python tuple wins.

    Type violations raise :class:`TypeError`; all other constraint violations
    raise :class:`ValueError`.
    """
    left_clock, left_records = _validated_state(left)
    right_clock, right_records = _validated_state(right)

    merged_clock: dict[str, int] = {}
    for node in set(left_clock) | set(right_clock):
        merged_clock[node] = max(left_clock.get(node, 0), right_clock.get(node, 0))

    merged_records: dict[str, list[Any]] = {}
    for key in set(left_records) | set(right_records):
        left_record = left_records.get(key)
        right_record = right_records.get(key)
        if left_record is None:
            chosen = right_record
        elif right_record is None:
            chosen = left_record
        else:
            chosen = _resolve_record(left_record, right_record)
        value, deleted, record_clock, writer = chosen
        merged_records[key] = [value, deleted, dict(record_clock), writer]

    return {CLOCK: merged_clock, RECORDS: merged_records}

"""Idempotent receipts binding a state to an audit record.

A receipt only names an ``id`` and the two 64-char lowercase hex digests of
the state and audit record it binds; the state and audit bytes themselves
are never read or written here.  Receipts are kept in an index stored as
UTF-8 compact JSON::

    {"items":[{"audit":...,"id":...,"state":...},...],"version":1}\\n

The top-level keys are fixed in the order ``items`` then ``version`` and
``version`` is always the integer 1.  ``items`` is an array of records
sorted ascending by ``id`` (ids are unique); each record carries the str
keys ``id``, ``state`` and ``audit`` and is canonically encoded with the
key order ``audit``, ``id``, ``state``.  Non-ASCII characters are preserved
unescaped and the file ends with exactly one ``\\n``.

A missing index file stands for an empty index; an existing file that
violates any byte, structure, order or field rule is corrupt.
"""

from __future__ import annotations

import json
import os
import re
from typing import Any

AUDIT = "audit"
ID = "id"
STATE = "state"

ITEMS = "items"
VERSION = "version"

_RECEIPT_KEYS = (ID, STATE, AUDIT)
_RECORD_KEYS = (AUDIT, ID, STATE)
_INDEX_KEYS = (ITEMS, VERSION)
_INDEX_VERSION = 1

_ID_RE = re.compile(r"[A-Za-z0-9._-]{1,64}\Z")
_DIGEST_RE = re.compile(r"[0-9a-f]{64}\Z")


class CorruptReceiptError(ValueError):
    """The receipt index exists but its bytes are not a valid index."""


def _is_digest(value: Any) -> bool:
    return isinstance(value, str) and _DIGEST_RE.fullmatch(value) is not None


def _validated_receipt(receipt: Any) -> dict[str, str]:
    """Validate one receipt and return a fresh dict in record key order."""
    if not isinstance(receipt, dict):
        raise TypeError("receipt must be a dict")
    if set(receipt.keys()) != set(_RECEIPT_KEYS):
        raise ValueError(
            "receipt must contain exactly the keys 'id', 'state' and 'audit'"
        )
    for key in _RECEIPT_KEYS:
        if not isinstance(receipt[key], str):
            raise TypeError(f"receipt {key} must be a str")
    receipt_id = receipt[ID]
    if _ID_RE.fullmatch(receipt_id) is None:
        raise ValueError("receipt id must match [A-Za-z0-9._-]{1,64}")
    if not _is_digest(receipt[STATE]):
        raise ValueError("receipt state must be 64 lowercase hex characters")
    if not _is_digest(receipt[AUDIT]):
        raise ValueError("receipt audit must be 64 lowercase hex characters")
    return {AUDIT: receipt[AUDIT], ID: receipt_id, STATE: receipt[STATE]}


def _serialize_index(records: list[dict[str, str]]) -> bytes:
    ordered = [
        {AUDIT: record[AUDIT], ID: record[ID], STATE: record[STATE]}
        for record in records
    ]
    index = {ITEMS: ordered, VERSION: _INDEX_VERSION}
    text = json.dumps(index, ensure_ascii=False, separators=(",", ":")) + "\n"
    return text.encode("utf-8")


def _parse_index(raw: bytes) -> list[dict[str, str]]:
    """Validate every byte of a receipt index and return its records.

    Raises :class:`CorruptReceiptError` for any UTF-8/JSON failure,
    non-canonical byte encoding, wrong key set or order, bad version,
    duplicate or unsorted ids, or a field that is not a well-formed str.
    """
    if raw == b"":
        raise CorruptReceiptError("receipt index is empty")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptReceiptError("receipt index is not valid UTF-8") from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise CorruptReceiptError("receipt index is not valid JSON") from exc

    if not isinstance(data, dict):
        raise CorruptReceiptError("receipt index must be a JSON object")
    if set(data.keys()) != set(_INDEX_KEYS):
        raise CorruptReceiptError(
            "receipt index must contain exactly the keys 'items' and 'version'"
        )
    if list(data.keys()) != list(_INDEX_KEYS):
        raise CorruptReceiptError(
            "receipt index keys must be in the order 'items', 'version'"
        )
    version = data[VERSION]
    # bool is a subclass of int; the version must be a genuine integer.
    if isinstance(version, bool) or not isinstance(version, int) or version != 1:
        raise CorruptReceiptError("receipt index version must be the integer 1")
    raw_items = data[ITEMS]
    if not isinstance(raw_items, list):
        raise CorruptReceiptError("receipt index items must be an array")

    records: list[dict[str, str]] = []
    for position, item in enumerate(raw_items):
        where = f"receipt index item {position}"
        if not isinstance(item, dict):
            raise CorruptReceiptError(f"{where} must be a JSON object")
        if set(item.keys()) != set(_RECORD_KEYS):
            raise CorruptReceiptError(
                f"{where} must contain exactly the keys 'audit', 'id' and 'state'"
            )
        if list(item.keys()) != list(_RECORD_KEYS):
            raise CorruptReceiptError(
                f"{where} keys must be in the order 'audit', 'id', 'state'"
            )
        audit_digest = item[AUDIT]
        record_id = item[ID]
        state_digest = item[STATE]
        if not isinstance(record_id, str) or _ID_RE.fullmatch(record_id) is None:
            raise CorruptReceiptError(f"{where} has an invalid id")
        if not _is_digest(state_digest):
            raise CorruptReceiptError(
                f"{where} state must be 64 lowercase hex characters"
            )
        if not _is_digest(audit_digest):
            raise CorruptReceiptError(
                f"{where} audit must be 64 lowercase hex characters"
            )
        records.append(
            {AUDIT: audit_digest, ID: record_id, STATE: state_digest}
        )

    ids = [record[ID] for record in records]
    if any(left >= right for left, right in zip(ids, ids[1:])):
        raise CorruptReceiptError(
            "receipt index ids must be unique and sorted ascending"
        )

    # Reject stray whitespace, non-canonical escapes, and any encoding that
    # is not the single compact form of the validated structure.
    if _serialize_index(records) != raw:
        raise CorruptReceiptError("receipt index is not canonically encoded")
    return records


def _read_index(path: str) -> list[dict[str, str]]:
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return []
    return _parse_index(raw)


def _atomic_write(path: str, payload: bytes) -> None:
    tmp_path = path + ".tmp"
    with open(tmp_path, "wb") as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    try:
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise
    fd = os.open(os.path.dirname(os.path.abspath(path)), os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def put(path: str, receipt: dict[str, str]) -> dict[str, str]:
    """Bind ``receipt``'s state and audit digests under its id in the index.

    A new id is added and the index is atomically replaced.  Putting the
    same id with identical state and audit digests is idempotent: a fresh
    dict is returned without touching the file bytes.  The same id with
    different digests raises :class:`ValueError` and leaves the file
    unchanged.  The returned dict always has the key order
    ``audit``, ``id``, ``state``.

    Type violations raise :class:`TypeError`; a bad key set, id or digest
    format raises :class:`ValueError`; a corrupt index raises
    :class:`CorruptReceiptError`; other filesystem errors propagate as
    :class:`OSError`.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    record = _validated_receipt(receipt)

    records = _read_index(path)
    for existing in records:
        if existing[ID] == record[ID]:
            if (
                existing[STATE] != record[STATE]
                or existing[AUDIT] != record[AUDIT]
            ):
                raise ValueError(
                    f"receipt id {record[ID]!r} is already bound to a "
                    "different state or audit record"
                )
            # Idempotent replay: brand-new copy, no filesystem change.
            return dict(record)

    records.append(record)
    records.sort(key=lambda entry: entry[ID])
    _atomic_write(path, _serialize_index(records))
    return dict(record)


def get(path: str, id: str) -> dict[str, str] | None:
    """Return a fresh copy of the receipt stored under ``id``, or None.

    A missing index file or an index without that id yields ``None``.
    Type violations raise :class:`TypeError`; a malformed ``id`` raises
    :class:`ValueError`; a corrupt index raises
    :class:`CorruptReceiptError`; other filesystem errors propagate as
    :class:`OSError`.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    if not isinstance(id, str):
        raise TypeError("id must be a str")
    if _ID_RE.fullmatch(id) is None:
        raise ValueError("id must match [A-Za-z0-9._-]{1,64}")

    for record in _read_index(path):
        if record[ID] == id:
            return dict(record)
    return None

from __future__ import annotations

import argparse
import json


def status() -> dict[str, object]:
    return {
        "nodeId": "local-node",
        "connectivity": "offline",
        "revision": 0,
        "pendingChanges": 0,
    }


def main() -> int:
    parser = argparse.ArgumentParser(prog="offline-coordination")
    parser.add_argument("command", choices=["status"])
    args = parser.parse_args()
    if args.command == "status":
        print(json.dumps(status(), sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Tests for read-only merge planning over audit proofs (plan_merge)."""

import hashlib
import hmac
import json
import os
import tempfile
import unittest
from unittest import mock

from offline_coordination import replication as R
from offline_coordination.replication import (
    InvalidProofError,
    compare_proofs,
    export_proof,
    plan_merge,
)

PLAN_KEYS = (
    "common",
    "left",
    "policy",
    "relation",
    "right",
    "steps",
    "unresolved",
    "version",
)
SIDE_KEYS = ("digest", "endSeq", "startSeq")
STEP_KEYS = ("action", "entry", "reason", "side")
UNRESOLVED_KEYS = ("side", "seq")

SECRET_A = "a" * 64


def canonical(obj):
    return json.dumps(
        obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")


def decoded(raw):
    return json.loads(raw)


def boundary(tag, seq):
    return hashlib.sha256(f"{tag}:{seq}".encode("utf-8")).hexdigest()


def synth_proof(start, end, tag="A", mutate=None):
    """Build a self-consistent valid proof for a synthetic chain.

    Entry at seq s chains boundary(tag, s-1) -> boundary(tag, s).  Two
    proofs with the same tag agree entry by entry at shared seqs; a
    different tag forks at every entry.
    """
    entries = []
    for seq in range(start, end + 1):
        entry = {
            "after": boundary(tag, seq),
            "before": boundary(tag, seq - 1),
            "id": f"{tag}-r{seq}",
            "seq": seq,
            "source": f"node-{tag}",
        }
        if mutate is not None:
            updated = mutate(seq, entry)
            if updated is not None:
                entry = updated
        entries.append(entry)
    data = {
        "endSeq": end,
        "entries": entries,
        "firstBefore": entries[0]["before"],
        "lastAfter": entries[-1]["after"],
        "startSeq": start,
        "version": 1,
    }
    data["digest"] = hashlib.sha256(canonical(data)).hexdigest()
    return canonical(data) + b"\n"


def fork_proof(start, end, fork_at, tag="A"):
    """A chain plus an id-only fork at ``fork_at`` sharing the prior boundary."""
    def change_id(seq, entry):
        if seq == fork_at:
            entry["id"] = f"{tag}-other"
        return entry

    return (
        synth_proof(start, end, tag),
        synth_proof(start, end, tag, mutate=change_id),
    )


def state(clock=None, records=None):
    return {"clock": dict(clock or {}), "records": dict(records or {})}


def record(value, n, writer="node-a"):
    return [value, False, {writer: n}, writer]


def make_request(rid, base, remote, source="node-a"):
    return {"id": rid, "source": source, "base": base, "remote": remote}


def seed_ledger(path, n=4):
    cur = state()
    for i in range(1, n + 1):
        nxt = state({"node-a": i}, {"k": record(f"v{i}", i)})
        result = R.apply_remote(path, make_request(f"r{i}", cur, nxt))
        assert result["status"] == "applied", result["status"]
        cur = nxt
    return cur


def signed_envelope(request_obj, node="node-a", key_version=1, secret=SECRET_A):
    payload = json.dumps(
        {"keyVersion": key_version, "node": node, "request": request_obj},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    signature = hmac.new(
        bytes.fromhex(secret), payload, hashlib.sha256
    ).hexdigest()
    return {
        "node": node,
        "keyVersion": key_version,
        "request": request_obj,
        "signature": signature,
    }


def keyring():
    return {
        "node-a": [
            {
                "version": 1,
                "secret": SECRET_A,
                "notBefore": 0,
                "notAfter": 100,
                "revoked": False,
            }
        ]
    }


class PlanShapeTest(unittest.TestCase):
    def test_plan_is_canonical_compact_json_with_one_lf(self) -> None:
        raw = plan_merge(synth_proof(1, 2), synth_proof(1, 3), "manual")
        self.assertTrue(raw.endswith(b"\n"))
        self.assertFalse(raw.endswith(b"\n\n"))
        self.assertEqual(raw, canonical(decoded(raw)) + b"\n")
        self.assertNotIn(b", ", raw)
        self.assertNotIn(b": ", raw)

    def test_top_level_keys_fixed_and_sorted(self) -> None:
        raw = plan_merge(synth_proof(1, 2), synth_proof(1, 3), "left")
        self.assertEqual(tuple(decoded(raw).keys()), PLAN_KEYS)

    def test_version_is_integer_1(self) -> None:
        plan = decoded(plan_merge(synth_proof(1, 2), synth_proof(1, 2), "right"))
        self.assertEqual(plan["version"], 1)
        self.assertIsInstance(plan["version"], int)
        self.assertNotIsInstance(plan["version"], bool)

    def test_policy_is_recorded_verbatim(self) -> None:
        for policy in ("left", "right", "manual"):
            plan = decoded(
                plan_merge(synth_proof(1, 2), synth_proof(1, 2), policy)
            )
            self.assertEqual(plan["policy"], policy)

    def test_sides_carry_digest_and_range(self) -> None:
        left = synth_proof(2, 4, "A")
        right = synth_proof(3, 5, "A")
        plan = decoded(plan_merge(left, right, "manual"))
        self.assertEqual(tuple(plan["left"].keys()), SIDE_KEYS)
        self.assertEqual(tuple(plan["right"].keys()), SIDE_KEYS)
        self.assertEqual(plan["left"]["startSeq"], 2)
        self.assertEqual(plan["left"]["endSeq"], 4)
        self.assertEqual(plan["left"]["digest"], decoded(left)["digest"])
        self.assertEqual(plan["right"]["startSeq"], 3)
        self.assertEqual(plan["right"]["endSeq"], 5)
        self.assertEqual(plan["right"]["digest"], decoded(right)["digest"])

    def test_common_keeps_the_boundary_shape(self) -> None:
        plan = decoded(plan_merge(synth_proof(1, 2), synth_proof(1, 4), "left"))
        self.assertEqual(
            plan["common"], {"after": boundary("A", 2), "seq": 2}
        )
        self.assertEqual(tuple(plan["common"].keys()), ("after", "seq"))

    def test_step_keys_fixed_and_sorted(self) -> None:
        plan = decoded(plan_merge(synth_proof(1, 2), synth_proof(1, 3), "left"))
        self.assertEqual(len(plan["steps"]), 1)
        self.assertEqual(tuple(plan["steps"][0].keys()), STEP_KEYS)

    def test_unresolved_items_carry_only_side_and_seq(self) -> None:
        left, right = fork_proof(1, 3, 1)
        plan = decoded(plan_merge(left, right, "manual"))
        self.assertTrue(plan["unresolved"])
        for ref in plan["unresolved"]:
            self.assertEqual(set(ref.keys()), set(UNRESOLVED_KEYS))

    def test_byte_stable_for_equal_inputs(self) -> None:
        left, right = fork_proof(1, 3, 2)
        for policy in ("left", "right", "manual"):
            self.assertEqual(
                plan_merge(left, right, policy),
                plan_merge(bytes(left), bytes(right), policy),
            )

    def test_inputs_are_not_modified(self) -> None:
        left, right = fork_proof(1, 3, 2)
        left_before, right_before = bytes(left), bytes(right)
        plan_merge(left, right, "manual")
        self.assertEqual(left, left_before)
        self.assertEqual(right, right_before)

    def test_no_file_is_opened(self) -> None:
        with mock.patch("builtins.open") as patched:
            plan_merge(synth_proof(1, 2), synth_proof(1, 3), "manual")
        patched.assert_not_called()

    def test_non_ascii_entries_stay_unescaped(self) -> None:
        def accent(seq, entry):
            entry["id"] = f"réq-{seq}"
            entry["source"] = "nœud-α"
            return entry

        left = synth_proof(1, 2, "A", mutate=accent)
        right = synth_proof(1, 3, "A", mutate=accent)
        raw = plan_merge(left, right, "manual")
        self.assertNotIn(b"\\u", raw)
        self.assertIn("réq-3".encode("utf-8"), raw)
        self.assertIn("nœud-α".encode("utf-8"), raw)

    def test_relation_common_and_sides_match_compare_proofs(self) -> None:
        scenarios = [
            (synth_proof(1, 3), synth_proof(1, 3)),
            (synth_proof(1, 2), synth_proof(1, 4)),
            (synth_proof(1, 4), synth_proof(1, 2)),
            (synth_proof(2, 5), synth_proof(4, 7)),
            (synth_proof(1, 4, "A"), synth_proof(1, 4, "B")),
        ]
        for left, right in scenarios:
            try:
                plan = decoded(plan_merge(left, right, "manual"))
            except ValueError:
                continue  # no planable boundary; compare_proofs still works
            report = decoded(compare_proofs(left, right))
            self.assertEqual(plan["relation"], report["relation"])
            self.assertEqual(plan["common"], report["common"])
            self.assertEqual(plan["left"], report["left"])
            self.assertEqual(plan["right"], report["right"])


class PlanValidationTest(unittest.TestCase):
    def setUp(self) -> None:
        self.good = synth_proof(1, 3)

    def test_non_bytes_proofs_raise_type_error(self) -> None:
        for bad in (self.good.decode("utf-8"), bytearray(self.good), None, 1, []):
            with self.assertRaises(TypeError):
                plan_merge(bad, self.good, "manual")
            with self.assertRaises(TypeError):
                plan_merge(self.good, bad, "manual")
            with self.assertRaises(TypeError):
                plan_merge(bad, bad, "manual")

    def test_non_str_policy_raises_type_error(self) -> None:
        for bad in (None, 1, True, ["left"], b"left"):
            with self.assertRaises(TypeError):
                plan_merge(self.good, self.good, bad)

    def test_type_errors_are_not_masked_by_bad_proofs(self) -> None:
        with self.assertRaises(TypeError):
            plan_merge(b"garbage\n", self.good, None)
        with self.assertRaises(TypeError):
            plan_merge(self.good, b"garbage\n", 1)
        with self.assertRaises(TypeError):
            plan_merge(b"garbage\n", b"junk\n", ["left"])

    def test_invalid_left_raises_invalid_proof_error(self) -> None:
        with self.assertRaises(InvalidProofError):
            plan_merge(b"garbage\n", self.good, "manual")

    def test_invalid_right_raises_invalid_proof_error(self) -> None:
        with self.assertRaises(InvalidProofError):
            plan_merge(self.good, b"garbage\n", "manual")

    def test_unknown_policy_raises_value_error(self) -> None:
        for bad in ("", "LEFT", "auto", "manual ", "lef", "right\n"):
            with self.assertRaises(ValueError):
                plan_merge(self.good, self.good, bad)

    def test_disjoint_ranges_raise_value_error(self) -> None:
        for policy in ("left", "right", "manual"):
            with self.assertRaises(ValueError):
                plan_merge(synth_proof(1, 2), synth_proof(4, 5), policy)

    def test_fork_without_common_boundary_raises_value_error(self) -> None:
        # Different tags fork at every shared entry with different before
        # digests, so no common boundary can be confirmed.
        for policy in ("left", "right", "manual"):
            with self.assertRaises(ValueError):
                plan_merge(synth_proof(1, 3, "A"), synth_proof(1, 3, "B"), policy)

    def test_fork_without_boundary_at_subrange_raises_value_error(self) -> None:
        for policy in ("left", "right", "manual"):
            with self.assertRaises(ValueError):
                plan_merge(synth_proof(2, 4, "A"), synth_proof(2, 4, "B"), policy)


class UnforkedPlanTest(unittest.TestCase):
    def test_same_relation_has_no_steps(self) -> None:
        plan = decoded(plan_merge(synth_proof(1, 3), synth_proof(1, 3), "manual"))
        self.assertEqual(plan["relation"], "same")
        self.assertEqual(plan["steps"], [])
        self.assertEqual(plan["unresolved"], [])

    def test_left_prefix_accepts_right_tail_as_extension(self) -> None:
        plan = decoded(plan_merge(synth_proof(1, 2), synth_proof(1, 4), "left"))
        self.assertEqual(plan["relation"], "left-prefix")
        self.assertEqual(
            [(s["side"], s["action"], s["reason"], s["entry"]["seq"])
             for s in plan["steps"]],
            [("right", "accept", "extension", 3),
             ("right", "accept", "extension", 4)],
        )
        self.assertEqual(plan["unresolved"], [])

    def test_right_prefix_accepts_left_tail_as_extension(self) -> None:
        plan = decoded(plan_merge(synth_proof(1, 4), synth_proof(1, 2), "right"))
        self.assertEqual(plan["relation"], "right-prefix")
        self.assertEqual(
            [(s["side"], s["action"], s["reason"], s["entry"]["seq"])
             for s in plan["steps"]],
            [("left", "accept", "extension", 3),
             ("left", "accept", "extension", 4)],
        )

    def test_overlap_accepts_the_longer_tail(self) -> None:
        plan = decoded(plan_merge(synth_proof(2, 5), synth_proof(4, 7), "manual"))
        self.assertEqual(plan["relation"], "overlap")
        self.assertEqual(plan["common"], {"after": boundary("A", 5), "seq": 5})
        self.assertEqual(
            [(s["side"], s["entry"]["seq"]) for s in plan["steps"]],
            [("right", 6), ("right", 7)],
        )
        for step in plan["steps"]:
            self.assertEqual(step["action"], "accept")
            self.assertEqual(step["reason"], "extension")

    def test_overlap_ending_at_the_boundary_has_no_steps(self) -> None:
        plan = decoded(plan_merge(synth_proof(1, 4), synth_proof(2, 4), "left"))
        self.assertEqual(plan["relation"], "overlap")
        self.assertEqual(plan["steps"], [])
        self.assertEqual(plan["unresolved"], [])

    def test_boundary_entries_are_never_repeated(self) -> None:
        left = synth_proof(1, 2)
        right = synth_proof(1, 5)
        plan = decoded(plan_merge(left, right, "manual"))
        boundary_seq = plan["common"]["seq"]
        self.assertEqual(boundary_seq, 2)
        for step in plan["steps"]:
            self.assertGreater(step["entry"]["seq"], boundary_seq)
        covered = {step["entry"]["seq"] for step in plan["steps"]}
        self.assertEqual(covered, {3, 4, 5})

    def test_policy_does_not_discard_unforked_extensions(self) -> None:
        # With no fork there is nothing to select: every policy accepts
        # the longer side's tail.
        for policy in ("left", "right", "manual"):
            plan = decoded(plan_merge(synth_proof(1, 2), synth_proof(1, 3), policy))
            self.assertEqual(len(plan["steps"]), 1)
            self.assertEqual(plan["steps"][0]["action"], "accept")
            self.assertEqual(plan["steps"][0]["reason"], "extension")


class ForkPlanTest(unittest.TestCase):
    def forked(self, start, end, fork_at, tag="A"):
        return fork_proof(start, end, fork_at, tag)

    def test_left_policy_accepts_left_and_rejects_right(self) -> None:
        left, right = self.forked(1, 4, 2)
        plan = decoded(plan_merge(left, right, "left"))
        self.assertEqual(plan["relation"], "fork")
        self.assertEqual(plan["common"], {"after": boundary("A", 1), "seq": 1})
        self.assertEqual(
            [(s["side"], s["action"], s["reason"], s["entry"]["seq"])
             for s in plan["steps"]],
            [("left", "accept", "selected", 2),
             ("right", "reject", "rejected", 2),
             ("left", "accept", "selected", 3),
             ("right", "reject", "rejected", 3),
             ("left", "accept", "selected", 4),
             ("right", "reject", "rejected", 4)],
        )
        self.assertEqual(plan["unresolved"], [])

    def test_right_policy_is_fully_symmetric(self) -> None:
        left, right = self.forked(1, 4, 2)
        plan = decoded(plan_merge(left, right, "right"))
        self.assertEqual(
            [(s["side"], s["action"], s["reason"], s["entry"]["seq"])
             for s in plan["steps"]],
            [("left", "reject", "rejected", 2),
             ("right", "accept", "selected", 2),
             ("left", "reject", "rejected", 3),
             ("right", "accept", "selected", 3),
             ("left", "reject", "rejected", 4),
             ("right", "accept", "selected", 4)],
        )
        self.assertEqual(plan["unresolved"], [])

    def test_manual_marks_both_tails_without_selecting(self) -> None:
        left, right = self.forked(1, 3, 1)
        plan = decoded(plan_merge(left, right, "manual"))
        self.assertEqual(
            [(s["side"], s["action"], s["reason"], s["entry"]["seq"])
             for s in plan["steps"]],
            [("left", "manual", "manual", 1),
             ("right", "manual", "manual", 1),
             ("left", "manual", "manual", 2),
             ("right", "manual", "manual", 2),
             ("left", "manual", "manual", 3),
             ("right", "manual", "manual", 3)],
        )

    def test_manual_unresolved_references_follow_step_order(self) -> None:
        left, right = self.forked(1, 3, 1)
        plan = decoded(plan_merge(left, right, "manual"))
        expected = [
            {"side": step["side"], "seq": step["entry"]["seq"]}
            for step in plan["steps"]
            if step["action"] == "manual"
        ]
        self.assertEqual(plan["unresolved"], expected)
        refs = [(ref["side"], ref["seq"]) for ref in plan["unresolved"]]
        self.assertEqual(len(refs), len(set(refs)))

    def test_steps_sorted_by_seq_with_left_first_on_ties(self) -> None:
        # Left covers 1..4, right 1..3, forking at seq 1 with a shared
        # prior boundary: the left tail is longer and still interleaves.
        left, right = self.forked(1, 4, 1)
        right = decoded(right)
        right["entries"] = right["entries"][:3]
        right["endSeq"] = 3
        right["lastAfter"] = right["entries"][-1]["after"]
        digestless = {k: v for k, v in right.items() if k != "digest"}
        right["digest"] = hashlib.sha256(canonical(digestless)).hexdigest()
        right = canonical(right) + b"\n"

        plan = decoded(plan_merge(left, right, "manual"))
        self.assertEqual(
            [(s["side"], s["entry"]["seq"]) for s in plan["steps"]],
            [("left", 1), ("right", 1),
             ("left", 2), ("right", 2),
             ("left", 3), ("right", 3),
             ("left", 4)],
        )

    def test_entries_are_carried_unchanged(self) -> None:
        left, right = self.forked(1, 4, 2)
        plan = decoded(plan_merge(left, right, "left"))
        left_entries = {e["seq"]: e for e in decoded(left)["entries"]}
        right_entries = {e["seq"]: e for e in decoded(right)["entries"]}
        for step in plan["steps"]:
            source = left_entries if step["side"] == "left" else right_entries
            self.assertEqual(step["entry"], source[step["entry"]["seq"]])

    def test_fork_in_subrange_plans_only_past_the_boundary(self) -> None:
        left, right = self.forked(3, 6, 3)
        plan = decoded(plan_merge(left, right, "left"))
        self.assertEqual(plan["common"], {"after": boundary("A", 2), "seq": 2})
        seqs = {step["entry"]["seq"] for step in plan["steps"]}
        self.assertEqual(seqs, {3, 4, 5, 6})


class MirrorTest(unittest.TestCase):
    def mirrored_steps(self, steps):
        """Steps with left/right labels flipped, back in canonical order."""
        flipped = [
            {
                "action": step["action"],
                "entry": step["entry"],
                "reason": step["reason"],
                "side": {"left": "right", "right": "left"}[step["side"]],
            }
            for step in steps
        ]
        flipped.sort(
            key=lambda step: (step["entry"]["seq"], step["side"] != "left")
        )
        return flipped

    def test_swap_with_mirrored_policy_mirrors_left_right(self) -> None:
        a, b = fork_proof(1, 4, 1)
        one = decoded(plan_merge(a, b, "left"))
        two = decoded(plan_merge(b, a, "right"))
        self.assertEqual(one["relation"], two["relation"])
        self.assertEqual(one["common"], two["common"])
        self.assertEqual(one["left"], two["right"])
        self.assertEqual(one["right"], two["left"])
        self.assertEqual(self.mirrored_steps(one["steps"]), two["steps"])
        self.assertEqual(one["unresolved"], two["unresolved"])

    def test_manual_swap_only_exchanges_sides(self) -> None:
        a, b = fork_proof(1, 3, 2)
        one = decoded(plan_merge(a, b, "manual"))
        two = decoded(plan_merge(b, a, "manual"))
        self.assertEqual(one["left"], two["right"])
        self.assertEqual(one["right"], two["left"])
        self.assertEqual(self.mirrored_steps(one["steps"]), two["steps"])
        mirrored_refs = sorted(
            (
                {
                    "side": {"left": "right", "right": "left"}[ref["side"]],
                    "seq": ref["seq"],
                }
                for ref in one["unresolved"]
            ),
            key=lambda ref: (ref["seq"], ref["side"] != "left"),
        )
        self.assertEqual(mirrored_refs, two["unresolved"])


