from offline_coordination.replication import resolve_merge, plan_merge
import hashlib, json

def canonical(obj):
    return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()

def boundary(tag, seq):
    return hashlib.sha256(f"{tag}:{seq}".encode()).hexdigest()

def synth(start, end, tag):
    entries = [{"after": boundary(tag, s), "before": boundary(tag, s-1),
                "id": f"{tag}-r{s}", "seq": s, "source": f"n-{tag}"} for s in range(start, end+1)]
    d = {"endSeq": end, "entries": entries, "firstBefore": entries[0]["before"],
         "lastAfter": entries[-1]["after"], "startSeq": start, "version": 1}
    d["digest"] = hashlib.sha256(canonical(d)).hexdigest()
    return canonical(d) + b"\n"

left, right = synth(1, 3, "A"), synth(1, 3, "B")
# fork with no common boundary -> plan_merge refuses
try:
    plan_merge(left, right, "manual")
except ValueError as e:
    print("plan_merge:", e)

# prefix extension, manual policy, empty decisions
p = plan_merge(synth(1, 2), synth(1, 4), "manual")
out = resolve_merge(p, synth(1, 2), synth(1, 4), [])
print(out.decode())
